 if(deviceMode&&!studentSession&&screen!=="teacherHelp"){const access=data.accessSettings[classId],sample=active[0],sampleCredential=sample&&data.studentCredentials.find(c=>c.studentId===sample.id);return <Shell><div className="kiosk-wait"><i>🌱</i><h1>마음씨앗 우체국</h1><h2>내 마음씨앗 카드를 보여주세요!</h2><div className="qr-camera"><span>▦</span><p>QR 카메라 영역</p></div>{deviceLoading?<div className="opening" role="status" aria-live="polite"><i>🌱</i><b>내 우체국을 열고 있어요...</b></div>:<>{process.env.NEXT_PUBLIC_SHOW_DEMO_ACCOUNTS!=="false"&&access?.qrEnabled&&<button className="scan-demo" onClick={()=>{if(!sampleCredential)return;setDeviceLoading(true);setTimeout(()=>{const found=validateQr(data,classId,sampleCredential.qrToken);setDeviceLoading(false);found?startStudent(found):setDeviceError("이 카드는 지금 사용할 수 없어요. 선생님께 보여주세요. 🌱")},500)}}>▦ Demo QR 스캔</button>}{access?.codeEnabled&&<div className="code-entry"><label>개인 코드<input value={codeInput} onChange={e=>setCodeInput(e.target.value.toUpperCase())}/></label><button onClick={()=>{const found=validatePersonalCode(data,classId,codeInput);found?startStudent(found):setDeviceError("이 코드는 지금 사용할 수 없어요. 선생님께 보여주세요. 🌱")}}>코드로 들어가기</button></div>}</>}{deviceError&&<div className="device-error" role="alert"><p>{deviceError}</p><button onClick={()=>setDeviceError("")}>다시 해볼래요</button></div>}<button className="teacher-help" onClick={()=>{setLoginId("");setLoginPassword("");setTeacherHelpVerified(false);setScreen("teacherHelp")}}>🔑 선생님 도움</button></div></Shell>}
 if(screen==="landing")return <Shell><section className="start-gate"><i>🌱</i><h1>마음씨앗 우체국</h1><p>마음과 발견을 소중히 담아요.</p><div className="start-choices"><button onClick={()=>setScreen("studentEntry")}><i>🌱</i><b>학생</b></button><button onClick={()=>setScreen("login")}><i>🧑‍🏫</i><b>선생님</b></button></div></section></Shell>;
 if(screen==="studentEntry")return <Shell><Head title="🌱 마음씨앗 우체국" back={()=>setScreen("landing")}/><section className="student-entry"><h1>어떻게 들어갈까요?</h1><div><button onClick={()=>{setStudentError("");setScreen("studentQr")}}><i>📷</i><b>QR로 들어가기</b><small>내 마음씨앗 카드를 보여줘요</small></button><button onClick={()=>{setStudentCode("");setStudentPin("");setStudentError("");setScreen("studentCode")}}><i>🔢</i><b>코드로 들어가기</b><small>학생 코드와 PIN을 써요</small></button></div></section></Shell>;

 if(screen==="studentQr")return <Shell><Head title="📷 QR로 들어가기" back={()=>{setStudentError("");history.replaceState({},"","/student");setScreen("studentEntry")}}/><section className="student-qr-entry"><i>🌱</i><h1>내 마음씨앗 카드를 준비해요</h1><StudentQrScanner onToken={token=>location.replace(`/student/enter/${encodeURIComponent(token)}`)} onCode={()=>{setStudentCode("");setStudentPin("");setStudentError("");history.replaceState({},"","/student");setScreen("studentCode")}}/>{studentError&&<p className="form-error" role="alert">{studentError}</p>}</section></Shell>;
 if(screen==="studentCode")return <Shell><Head title="🔢 코드로 들어가기" back={()=>{history.replaceState({},"","/student");setScreen("studentEntry")}}/><section className="student-code-entry"><i>🌱</i><h1>내 코드를 알려주세요.</h1><label>학생 코드<input autoFocus value={studentCode} onChange={e=>setStudentCode(e.target.value.toUpperCase())} placeholder="예: G7K4P2"/></label><label>PIN<input type="password" inputMode="numeric" value={studentPin} onChange={e=>setStudentPin(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="숫자 4자리"/></label>{studentError&&<p className="form-error">{studentError}</p>}<button className="primary" onClick={()=>{const found=cloudConfigured()?null:validateStudentLogin(data,studentCode,studentPin);if(found){setClassId(found.classId);sessionStorage.setItem("maeum-role","student");sessionStorage.setItem("maeum-student-id",found.student.id);sessionStorage.setItem("maeum-student-class",found.classId);setKidId(found.student.id);setStudentSession(true);setTeacherKidId("");setRelationKidId("");setSettingsMessage("");history.replaceState({},"","/student/home");setScreen("home")}else if(cloudConfigured()){resolveCloudCode(studentCode,studentPin).then(snapshot=>{if(!snapshot)throw new Error("invalid");const cloudState=mergeCloudSnapshot(data,snapshot);setData(cloudState);setClassId(snapshot.classData.id);setKidId(snapshot.student.id);setStudentSession(true);setTeacherKidId("");setRelationKidId("");sessionStorage.setItem("maeum-role","student");sessionStorage.setItem("maeum-student-id",snapshot.student.id);sessionStorage.setItem("maeum-student-class",snapshot.classData.id);loadStudentLetters(snapshot.student.id,snapshot.classData.id);history.replaceState({},"","/student/home");setScreen("home")}).catch(()=>setStudentError("학생 코드와 PIN을 다시 확인해 주세요."))}else setStudentError("학생 코드와 PIN을 다시 확인해 주세요.")}}>내 우체국 들어가기</button><small>여러 번 맞지 않으면 잠시 뒤 다시 시도해 주세요.</small></section></Shell>; if(screen==="teacherHelp"&&deviceMode&&!studentSession){return <Shell><Head title="선생님 도움" back={()=>setScreen("kiosk")}/>{!teacherHelpVerified?<div className="pin-card"><i>🔑</i><h2>교사 ID와 비밀번호를 다시 입력해 주세요.</h2><label>교사 ID<input value={loginId} onChange={e=>setLoginId(e.target.value.toUpperCase())}/></label><label>비밀번호<input type="password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)}/></label>{deviceError&&<p>{deviceError}</p>}<button type="button" disabled={deviceLoading} onClick={async()=>{if(deviceLoading)return;setDeviceLoading(true);setDeviceError("");try{if(cloudConfigured()){const bootstrap=await createCloudTeacherSession(loginId,loginPassword);if(!bootstrap||!bootstrap.classes?.some((item:any)=>item.id===classId))return setDeviceError("현재 교사 ID와 비밀번호를 다시 확인해 주세요.");setData(old=>mergeTeacherBootstrap(old,bootstrap,loginPassword))}else{const account=demoAuthService.login(loginId,loginPassword,data);if(!account||account.classId!==classId)return setDeviceError("교사 ID와 비밀번호를 다시 확인해 주세요.")}sessionStorage.removeItem("maeum-shared-class");sessionStorage.setItem("maeum-role","teacher");sessionStorage.setItem("maeum-teacher-class",classId);setDeviceMode(false);setTeacherHelpVerified(false);history.replaceState({},"","/teacher/dashboard");setScreen("dashboard")}finally{setDeviceLoading(false)}}}>{deviceLoading?"확인하고 있어요…":"확인"}</button></div>:<><h2>선생님이 학생을 선택해 주세요.</h2><Kids list={active} choose={startStudent}/><button className="device-exit" onClick={()=>{sessionStorage.removeItem("maeum-shared-class");setDeviceMode(false);setTeacherHelpVerified(false);setScreen("dashboard")}}>공용기기 모드 종료</button></>}</Shell>} if(screen==="login")return <Shell><div className="hero login-hero"><button className="entry-back" onClick={()=>setScreen("landing")}>← 처음으로</button><i>🌱</i><p>마음과 자연을 잇는 따뜻한 편지</p><h1>마음씨앗 우체국</h1><div className="login-box"><label>교사 ID<input value={loginId} onChange={e=>setLoginId(e.target.value.toUpperCase())} placeholder="교사 ID를 입력해 주세요"/></label><label>비밀번호<input type="password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} placeholder="비밀번호를 입력해 주세요"/></label>{loginNotice&&<p className="success" role="status">{loginNotice}</p>}{loginError&&<p className="form-error">{loginError}</p>}<button onClick={async()=>{setLoginNotice("");if(cloudConfigured()){const bootstrap=await createCloudTeacherSession(loginId,loginPassword);if(!bootstrap)return setLoginError("교사 ID 또는 비밀번호를 다시 확인해 주세요.");const firstClass=bootstrap.classes?.[0];if(!firstClass)return setLoginError("담당 학급을 찾지 못했어요.");const restored=mergeTeacherBootstrap(data,bootstrap,loginPassword),account=restored.accounts.find(item=>item.classId===firstClass.id)!;setData(restored);setClassId(firstClass.id);setStudentDirect(false);setLoginError("");setNewPass("");setConfirmPass("");sessionStorage.setItem("maeum-role","teacher");sessionStorage.setItem("maeum-teacher-class",firstClass.id);history.replaceState({},"","/teacher/dashboard");setScreen(account.mustChangePassword?"forcePassword":"dashboard");return}const account=demoAuthService.login(loginId,loginPassword,data);if(!account)return setLoginError("교사 ID 또는 비밀번호를 다시 확인해 주세요.");setClassId(account.classId);setStudentDirect(false);setLoginError("");setNewPass("");setConfirmPass("");sessionStorage.setItem("maeum-role","teacher");sessionStorage.setItem("maeum-teacher-class",account.classId);history.replaceState({},"","/teacher/dashboard");setScreen(account.mustChangePassword?"forcePassword":"dashboard")}}>교사 로그인</button><div className="login-divider"><span>또는</span></div><div className="first-teacher"><b>🌱 처음이신가요?</b><button onClick={()=>{setNewClassName("");setScreen("createClass")}}>학급 만들기</button><small>개인정보 입력 없이 교사 ID와 학급 코드를 발급받을 수 있어요.</small></div><button className="forgot-link" onClick={()=>{setSettingsMessage("");setLoginNotice("");setScreen("recover")}}>비밀번호를 잊으셨나요?</button></div>{process.env.NEXT_PUBLIC_SHOW_DEMO_ACCOUNTS!=="false"&&<div className="demo-accounts"><b>Demo 테스트 계정</b>{demoAccounts.map(a=><small key={a.classId}>{data.classes.find(c=>c.id===a.classId)?.name}: {a.teacherId} / 1234</small>)}</div>}</div></Shell>;
 if(screen==="createClass")return <Shell><Head title="새 마음씨앗 우체국 만들기" back={()=>setScreen("login")}/><div className="create-class-card"><i>🌱</i><h2>우리 반 이름을 알려주세요.</h2><label>학급 이름<input autoFocus value={newClassName} onChange={e=>setNewClassName(e.target.value)} placeholder="예: 해바라기반" disabled={registrationLoading}/></label>{registrationError&&<p className="form-error" role="alert">{registrationError}</p>}<button type="button" disabled={!newClassName.trim()||registrationLoading} onClick={async()=>{if(registrationLoading)return;setRegistrationLoading(true);setRegistrationError("");try{if(cloudConfigured()){const registered=await createCloudTeacherRegistration(newClassName);const restored=mergeTeacherBootstrap(data,{teacherCode:registered.teacherCode,recoveryKey:registered.recoveryKey,mustChangePassword:true,classes:[{...registered.classData,students:[],credentials:[]}]},registered.initialPassword),account=restored.accounts.find(item=>item.classId===registered.classData.id);if(!account)throw new Error("지금은 우리 반 우체국을 만들지 못했어요. 다시 시도해 주세요.");setData(restored);setIssued(account);setClassId(account.classId)}else{const result=demoAuthService.createClass(newClassName,data);setData(result.state);setIssued(result.account);setClassId(result.account.classId)}setSettingsMessage("");setScreen("issued")}catch(error){setRegistrationError(error instanceof Error?error.message:"지금은 우리 반 우체국을 만들지 못했어요. 다시 시도해 주세요.")}finally{setRegistrationLoading(false)}}}>{registrationLoading?"우리 반 우체국을 안전하게 만들고 있어요…":"🌱 학급 만들기"}</button><p>교사 이름, 이메일, 전화번호, 학교명은 입력하지 않아요.</p></div></Shell>;
 if(screen==="issued"&&issued){const className=data.classes.find(c=>c.id===issued.classId)?.name||newClassName,copyText=`${className} 마음씨앗 우체국\n교사 ID: ${issued.teacherId}\n초기 비밀번호: ${issued.password}\n학급 코드: ${issued.classCode}\n복구키: ${issued.recoveryKey}`;return <Shell><Head title="발급 완료" back={()=>setScreen("login")}/><div className="issued-wrap"><h2>🌱 마음씨앗 우체국이 만들어졌어요!</h2><p>아래 정보는 우리 반 마음씨앗 우체국을 관리할 때 필요해요.<br/>안전한 곳에 보관해 주세요.</p><article className="issue-card"><small>🌱 마음씨앗 우체국 · {className}</small><dl><div><dt>교사 ID</dt><dd>{issued.teacherId}</dd></div><div><dt>초기 비밀번호</dt><dd>{issued.password}</dd></div><div><dt>학급 코드</dt><dd>{issued.classCode}</dd></div><div><dt>복구키</dt><dd>{issued.recoveryKey}</dd></div></dl><p>이 정보는 학급을 관리하고 비밀번호를 복구할 때 필요합니다.</p></article><div className="issued-actions no-print"><button onClick={async()=>{await navigator.clipboard.writeText(copyText);setSettingsMessage("발급 정보를 복사했어요.")}}>📋 정보 복사하기</button><button onClick={e=>{const card=e.currentTarget.closest(".issued-wrap")?.querySelector(".issue-card");card?.classList.add("print-target");window.print();setTimeout(()=>card?.classList.remove("print-target"),100)}}>🖨 발급 정보 인쇄하기</button></div>{settingsMessage&&<p>{settingsMessage}</p>}<button className="primary no-print" type="button" disabled={issuedStarting} onClick={async()=>{if(issuedStarting)return;setIssuedStarting(true);setSettingsMessage("");try{if(cloudConfigured()){const bootstrap=await createCloudTeacherSession(issued.teacherId,issued.password);if(!bootstrap?.classes?.some((item:any)=>item.id===issued.classId))throw new Error("초기 비밀번호 인증을 확인해 주세요.");setData(old=>mergeTeacherBootstrap(old,{...bootstrap,recoveryKey:issued.recoveryKey,mustChangePassword:true},issued.password))}sessionStorage.setItem("maeum-role","teacher");sessionStorage.setItem("maeum-teacher-class",issued.classId);history.replaceState({},"","/teacher/password");setNewPass("");setConfirmPass("");setScreen("forcePassword")}catch(error){setSettingsMessage(error instanceof Error?error.message:"지금은 시작하지 못했어요. 다시 시도해 주세요.")}finally{setIssuedStarting(false)}}}>{issuedStarting?"확인하고 있어요…":"우리 반 시작하기"}</button></div></Shell>}
 if(screen==="forcePassword")return <Shell><Head title="새 비밀번호 만들기" back={()=>setScreen("login")}/><div className="password-card"><i>🔑</i><h2>처음 사용하시는 비밀번호예요.<br/>새 비밀번호로 바꿔주세요.</h2><label>새 비밀번호<input type="password" value={newPass} onChange={e=>setNewPass(e.target.value)} disabled={passwordChanging}/></label><label>새 비밀번호 확인<input type="password" value={confirmPass} onChange={e=>setConfirmPass(e.target.value)} disabled={passwordChanging}/></label>{settingsMessage&&<p className="form-error">{settingsMessage}</p>}<button type="button" disabled={passwordChanging} onClick={async()=>{if(passwordChanging)return;if(newPass.length<4)return setSettingsMessage("비밀번호는 4자리 이상으로 정해 주세요.");if(newPass!==confirmPass)return setSettingsMessage("새 비밀번호가 서로 일치하지 않아요.");setPasswordChanging(true);try{const account=data.accounts.find(item=>item.classId===classId);if(!account)throw new Error("교사 계정을 찾지 못했어요.");if(cloudConfigured())await changeCloudTeacherPassword(account.password,newPass);setData(old=>demoAuthService.setInitialPassword(classId,newPass,old));setSettingsMessage("");setLoginPassword("");history.replaceState({},"","/teacher/dashboard");setScreen("dashboard")}catch(error){setSettingsMessage(error instanceof Error?error.message:"비밀번호를 변경하지 못했어요.")}finally{setPasswordChanging(false)}}}>{passwordChanging?"새 비밀번호를 안전하게 저장하고 있어요…":"비밀번호 변경하고 시작하기"}</button></div></Shell>;
 if(screen==="recover")return <Shell><Head title="복구키로 비밀번호 다시 만들기" back={()=>setScreen("login")}/><div className="password-card"><i>🗝️</i><h2>복구키로 비밀번호 다시 만들기</h2><label>교사 ID<input value={recoverId} onChange={e=>setRecoverId(e.target.value.toUpperCase())}/></label><label>복구키<input value={recoverKey} onChange={e=>setRecoverKey(e.target.value.toUpperCase())} placeholder="XXXX-XXXX-XXXX"/></label><label>새 비밀번호<input type="password" value={recoverPassword} onChange={e=>setRecoverPassword(e.target.value)}/></label><label>새 비밀번호 확인<input type="password" value={recoverConfirm} onChange={e=>setRecoverConfirm(e.target.value)}/></label>{settingsMessage&&<p className="form-error">{settingsMessage}</p>}<button onClick={async()=>{if(recoverPassword.length<4)return setSettingsMessage("새 비밀번호는 4자리 이상으로 정해 주세요.");if(recoverPassword!==recoverConfirm)return setSettingsMessage("새 비밀번호가 서로 일치하지 않아요.");try{if(cloudConfigured())await recoverCloudTeacherPassword(recoverId,recoverKey,recoverPassword);else setData(old=>demoAuthService.recover(recoverId,recoverKey,recoverPassword,old));setLoginId(recoverId);setLoginPassword("");setSettingsMessage("");setLoginNotice("비밀번호를 새로 만들었어요.");setScreen("login")}catch(e){setSettingsMessage((e as Error).message)}}}>새 비밀번호 저장하기</button><p>이메일이나 전화번호 대신 발급 시 받은 복구키를 사용합니다.</p></div></Shell>; if(screen==="dashboard")return <Shell><Head title={`${cls.name} 교사 대시보드`} back={()=>{sessionStorage.setItem("maeum-role","anonymous");sessionStorage.removeItem("maeum-teacher-class");history.replaceState({},"","/");setLoginPassword("");setScreen("login")}}/><aside>오늘도 아이들의 마음을 천천히 살펴보세요.</aside><div className="menu"><Menu icon="👩‍🏫" name="교사와 함께하기" sub="우리 반 친구들과 함께 연습하거나 활동해요" go={()=>{history.replaceState({},"","/teacher/together");setScreen("together")}}/><Menu icon="💛" name="오늘의 마음" sub={`${active.filter(s=>data.moodHistory.some(m=>m.ownerId===s.id&&m.classId===classId&&new Date(m.createdAt).toDateString()===new Date().toDateString())).length}명 작성`} go={()=>setScreen("today")}/><Menu icon="📊" name="감정 이모지 살펴보기" sub="열람 가능한 기록만 분석" go={()=>setScreen("emotion")}/><Menu icon="🧒" name="개별 유아 보기" sub="기록과 교사 메모" go={()=>setScreen("individual")}/><Menu icon="🕸️" name="우리 반 관계지도" sub="자연 마음 선택 기록" go={()=>setScreen("relation")}/><Menu icon="🌿" name="마음 나눔 현황" sub="이번 마음 나눔 기록" go={()=>setScreen("cycle")}/><Menu icon="🖼️" name="우리 반 갤러리" sub="승인된 익명 기록" go={()=>setScreen("gallery")}/><Menu icon="💛" name="이번 달 공감나눔 친구" sub="서로 다른 친구에게 전한 마음" go={()=>setScreen("reactionReport")}/><Menu icon="💌" name="선생님 마음편지" sub="학생별 개인 피드백" go={()=>setScreen("letters")}/><Menu icon="🔎" name="오늘의 발견 관리" sub={data.discoveryTopics[classId]?.title||"주제 설정"} go={()=>setScreen("discoveryManage")}/><Menu icon="👥" name="유아 관리" sub={`활성 ${active.length}명`} go={()=>setScreen("manage")}/><Menu icon="♿" name="접근성 지원" sub="큰 버튼·음성·간단한 화면" go={()=>setScreen("accessibility")}/><Menu icon="⚙️" name="우리 반 기능 설정" sub="학생 메뉴 ON / OFF" go={()=>setScreen("features")}/><Menu icon="🖨️" name="인쇄 및 자료" sub="개별 카드 인쇄" go={()=>setScreen("individual")}/><Menu icon="⚙️" name="교사용 설정" sub="학급명과 비밀번호" go={()=>setScreen("settings")}/><Menu icon="📱" name="우리 반 기기 연결하기" sub="공용 태블릿 학생 모드" go={()=>setScreen("deviceSettings")}/><Menu icon="▦" name="학생 QR 카드 인쇄" sub="카드 인쇄와 재발급" go={()=>setScreen("qrCards")}/><Menu icon="📱" name="학생 화면 미리보기" sub="현재 열린 기능 확인" go={()=>setScreen("preview")}/><button className="tile dark" onClick={()=>setScreen("deviceSettings")}><i>📮</i><b>공용기기 시작</b><small>교사 화면과 분리</small></button></div></Shell>;

 if(screen==="deviceSettings"){const access=data.accessSettings[classId];const update=(patch:Partial<typeof access>)=>patchData(old=>({...old,accessSettings:{...old.accessSettings,[classId]:{...old.accessSettings[classId],...patch}}}));return <Shell><Head title={`${cls.name} 학생 입장 방법`} back={()=>setScreen("dashboard")}/><div className="access-settings"><h2>학생 입장 방법</h2><label><input type="checkbox" checked={access.qrEnabled} onChange={e=>update({qrEnabled:e.target.checked})}/>▦ QR 카드</label><label><input type="checkbox" checked={access.codeEnabled} onChange={e=>update({codeEnabled:e.target.checked})}/>🔢 개인 코드</label><h2>사용 장소</h2><label><input type="checkbox" checked={access.sharedDevice} onChange={e=>update({sharedDevice:e.target.checked})}/>📱 공용 태블릿 사용</label><label><input type="checkbox" checked={access.homeQrAllowed} onChange={e=>update({homeQrAllowed:e.target.checked})}/>🏠 가정에서 학생 QR 사용 허용</label><p>QR 카드와 학생 개인코드에는 이름·학교·전화번호·이메일을 넣지 않습니다.</p><button className="primary" disabled={!access.sharedDevice||(!access.qrEnabled&&!access.codeEnabled)} onClick={()=>{setData(old=>ensureCredentials(old));sessionStorage.setItem("maeum-shared-class",classId);sessionStorage.setItem("maeum-role","device");history.replaceState({},"","/device/wait");setDeviceMode(true);setStudentSession(false);setKidId("");setScreen("kiosk")}}>📱 이 기기를 우리 반 공용기기로 연결</button></div></Shell>}
 if(screen==="qrCards"){const qrBase=appBaseUrl(),credentials=active.map(s=>({s,c:data.studentCredentials.find(x=>x.studentId===s.id)})).filter(x=>x.c);const print=(target:Element|null)=>{target?.classList.add("print-target");window.print();setTimeout(()=>target?.classList.remove("print-target"),100)};return <Shell><Head title={`${cls.name} 학생 QR 카드`} back={()=>setScreen("dashboard")}/><div className="qr-toolbar no-print"><button onClick={e=>print(e.currentTarget.parentElement?.nextElementSibling||null)}>🖨 우리 반 마음씨앗 카드 인쇄</button><button onClick={()=>{if(!confirm("학생 접속정보가 포함된 파일입니다. 안전한 곳에 보관해 주세요. 다운로드할까요?"))return;const rows=active.map((x,i)=>{const c=data.studentCredentials.find(v=>v.studentId===x.id);return [i+1,x.name,c?.studentCode||"",c?.pin||"기존 PIN 확인 불가",x.active?"사용":"비활성"]}),csv="\\uFEFF번호,학생 이름,학생 코드,초기 PIN,활성상태\\n"+rows.map(r=>r.join(",")).join("\\n"),url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download=`${cls.name}-학생접속정보.csv`;a.click();URL.revokeObjectURL(url)}}>📥 접속정보 CSV 다운로드</button><p>분실되거나 외부에 노출된 카드는 재발급할 수 있습니다. 인쇄 창에서 PDF로 저장할 수도 있어요.</p><aside className="qr-demo-limit"><b>현재 QR 기준 주소: {qrBase}</b><span>{cloudConfigured()?"QR은 Supabase credential과 연결됩니다. 기존 QR 카드는 계속 사용할 수 있습니다. 이 브라우저에서는 기존 QR 이미지를 다시 표시할 수 없으며, 새 카드가 필요할 때만 재발급해 주세요.":"Demo Mode 접속정보는 이 브라우저에만 저장됩니다."}</span></aside></div><div className="qr-card-grid">{credentials.map(({s,c})=><article className="student-qr-card" key={s.id}><i>{s.avatar}</i><h3>{s.name}</h3>{c!.qrToken?<StudentQrCode token={c!.qrToken} name={s.name}/>:<div className="qr-missing" role="status"><b>기존 QR 카드는 계속 사용할 수 있어요.</b><span>이 브라우저에서는 기존 QR 이미지를 다시 표시할 수 없습니다. 새 카드가 필요하면 QR을 재발급해 주세요. 재발급하면 기존 QR 카드는 사용할 수 없습니다.</span></div>}<b>내 마음씨앗 카드</b><small>학생 코드 {c!.studentCode}</small><small>PIN {c!.pin||"기존 PIN 확인 불가"}</small>{c!.qrToken&&<div className="qr-entry-address no-print"><small>{studentEntryUrl(c!.qrToken)}</small><button type="button" onClick={async()=>{await navigator.clipboard.writeText(studentEntryUrl(c!.qrToken));setStudentCloudMessage("입장 주소를 복사했어요.")}}>입장 주소 확인·복사</button></div>}<div className="qr-actions no-print"><button onClick={e=>print(e.currentTarget.closest(".student-qr-card"))}>인쇄</button><button onClick={e=>{const qr=e.currentTarget.closest(".student-qr-card")?.querySelector(".student-qr svg");if(!qr)return alert("QR을 만든 뒤 다시 눌러 주세요.");const qrMarkup=new XMLSerializer().serializeToString(qr),safeName=s.name.replace(/[<>&]/g,v=>({"<":"&lt;",">":"&gt;","&":"&amp;"}[v]!)),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="800" viewBox="0 0 600 800"><rect width="100%" height="100%" rx="32" fill="#fffdf7" stroke="#47725c" stroke-width="3"/><text x="300" y="100" text-anchor="middle" font-size="64">${s.avatar}</text><text x="300" y="170" text-anchor="middle" font-size="38" font-family="sans-serif">${safeName}</text><g transform="translate(110 210) scale(1.73)">${qrMarkup}</g><text x="300" y="650" text-anchor="middle" font-size="30" font-family="sans-serif">내 마음씨앗 카드</text><text x="300" y="700" text-anchor="middle" font-size="18" font-family="sans-serif">학생 코드 ${c!.studentCode}</text><text x="300" y="735" text-anchor="middle" font-size="18" font-family="sans-serif">PIN ${c!.pin||"기존 PIN 확인 불가"}</text></svg>`,url=URL.createObjectURL(new Blob([svg],{type:"image/svg+xml"})),a=document.createElement("a");a.href=url;a.download=`${s.name}-마음씨앗-QR카드.svg`;a.click();URL.revokeObjectURL(url)}}>QR 카드 다운로드</button><button type="button" disabled={cloudSaving} onClick={()=>{if(confirm(`${s.name}의 기존 QR 카드를 사용할 수 없게 하고 새로 발급할까요?`))void resetQr(s.id)}}>QR 재발급</button></div></article>)}</div></Shell>} if(screen==="accessibility"){const options=[{key:"largeTargets",icon:"🔎",name:"버튼 더 크게 보기"},{key:"audioPrompts",icon:"🔊",name:"안내 듣기 버튼"},{key:"simplifiedChoices",icon:"🌱",name:"한 화면 선택지 줄이기"},{key:"pictureGuidance",icon:"🖼️",name:"그림 중심 안내"},{key:"reducedMotion",icon:"🍃",name:"움직임 효과 줄이기"},{key:"extendedTimeout",icon:"⏳",name:"자동 종료 시간 늘리기"},{key:"tapAlternativeToDrag",icon:"👆",name:"드래그 대신 누르기 이동"},{key:"teacherHelp",icon:"🤝",name:"교사 도움 사용"}] as const,target=teacherKidId?{...classA11y,...(data.studentAccessibility[teacherKidId]||{})}:classA11y;const toggle=(key:typeof options[number]["key"])=>patchData(old=>teacherKidId?{...old,studentAccessibility:{...old.studentAccessibility,[teacherKidId]:{...(old.studentAccessibility[teacherKidId]||{}),[key]:!target[key]}}}:{...old,classAccessibility:{...old.classAccessibility,[classId]:{...old.classAccessibility[classId],[key]:!target[key]}}});return <Shell><Head title={`${cls.name} 접근성 지원`} back={()=>{setTeacherKidId("");setScreen("dashboard")}}/><aside>진단명은 저장하지 않습니다. 학생에게 필요한 조작과 안내 방식만 선택해 주세요.</aside><div className="a11y-scope"><button className={!teacherKidId?"selected":""} onClick={()=>setTeacherKidId("")}>🏫 우리 반 기본</button>{active.map(x=><button className={teacherKidId===x.id?"selected":""} key={x.id} onClick={()=>setTeacherKidId(x.id)}>{x.avatar} {x.name}</button>)}</div>{teacherKidId&&<button className="use-class-default" onClick={()=>patchData(old=>{const next={...old.studentAccessibility};delete next[teacherKidId];return{...old,studentAccessibility:next}})}>우리 반 기본 설정 사용</button>}<div className="a11y-options">{options.map(x=><button role="switch" aria-checked={target[x.key]} className={target[x.key]?"on":"off"} key={x.key} onClick={()=>toggle(x.key)}><i aria-hidden="true">{x.icon}</i><b>{x.name}</b><span>{target[x.key]?"켜짐":"꺼짐"}</span></button>)}</div></Shell>} if(screen==="features"){const reactionSettings=data.galleryReactionSettings[classId],patchReactionSettings=(patch:Partial<typeof reactionSettings>)=>patchData(old=>({...old,galleryReactionSettings:{...old.galleryReactionSettings,[classId]:{...old.galleryReactionSettings[classId],...patch}}}));return <Shell><Head title={`${cls.name} 우리 반 기능 설정`} back={()=>setScreen("dashboard")}/><aside>OFF한 기능은 학생 홈에서 숨겨지며 기존 기록은 삭제되지 않습니다.</aside><div className="feature-settings">{([{key:"mood",icon:"💛",name:"오늘 내 마음"},{key:"friend",icon:"💌",name:"오늘의 마음친구"},{key:"nature",icon:"🌿",name:"친구에게 자연마음"},{key:"capture",icon:"📸",name:"내 보물 찰칵"},{key:"discovery",icon:"🔎",name:"오늘의 발견"},{key:"treasure",icon:"🎁",name:"내 보물창고"},{key:"galleryReaction",icon:"❤️",name:"갤러리 공감"},{key:"teacherLetter",icon:"💌",name:"선생님 마음편지"}] as const).map(item=>{const on=data.features[classId][item.key];return <button className={on?"on":"off"} key={item.key} onClick={()=>patchData(old=>({...old,features:{...old.features,[classId]:{...old.features[classId],[item.key]:!on}}}))}><i>{item.icon}</i><b>{item.name}</b><span>{on?"ON":"OFF"}</span></button>})}</div><section className="reaction-settings"><h2>❤️ 갤러리 공감 세부 설정</h2><label><input type="checkbox" checked={reactionSettings.flowerEnabled} onChange={e=>patchReactionSettings({flowerEnabled:e.target.checked})}/>🌸 공감꽃 표시 <b>{reactionSettings.flowerEnabled?"ON":"OFF"}</b></label><label><input type="checkbox" checked={reactionSettings.monthlySharerEnabled} onChange={e=>patchReactionSettings({monthlySharerEnabled:e.target.checked})}/>💛 월간 공감나눔 친구 <b>{reactionSettings.monthlySharerEnabled?"ON":"OFF"}</b></label><label><input type="checkbox" checked={reactionSettings.exactCountsVisible} onChange={e=>patchReactionSettings({exactCountsVisible:e.target.checked})}/>학생에게 정확한 공감 수 표시 <b>{reactionSettings.exactCountsVisible?"ON":"OFF"}</b></label><label>공감꽃 기준<input type="number" min="1" max="25" value={reactionSettings.flowerThreshold} onChange={e=>patchReactionSettings({flowerThreshold:Math.max(1,Number(e.target.value)||1)})}/>명 이상</label><label>공감나눔 친구 기준<input type="number" min="1" max="25" value={reactionSettings.sharerThreshold} onChange={e=>patchReactionSettings({sharerThreshold:Math.max(1,Number(e.target.value)||1)})}/>서로 다른 친구 이상</label><p>기준을 충족한 모든 학생과 작품을 함께 축하하며 순위는 만들지 않습니다.</p></section></Shell>}
 if(screen==="preview")return <Shell><Head title={`${cls.name} 학생 화면 미리보기`} back={()=>{setTeacherKidId("");setScreen("dashboard")}}/><aside>미리보기는 교사 화면이며 실제 학생 세션을 만들지 않습니다. 학생을 선택해 현재 열린 메뉴를 확인하세요.</aside><div className="teacher-picker no-print">{active.map(s=><button className={teacherKidId===s.id?"selected":""} key={s.id} onClick={()=>setTeacherKidId(s.id)}>{s.avatar} {s.name}</button>)}</div>{teacherKid?<><div className="preview-title">{teacherKid.avatar} {teacherKid.name}의 학생 화면</div><StudentHome features={data.features[classId]} unreadLetter={false} moodLabel="내 마음을 담아요" go={()=>{}}/></>:<Empty text="미리 볼 학생을 선택해 주세요."/>}</Shell>;
 if(screen==="emotion")return <Shell><Head title={`${cls.name} 감정 이모지 살펴보기`} back={()=>setScreen("dashboard")}/><aside>함께 보기와 선생님과 학생 기록만 분석합니다. 학생만 보는 마음의 실제 내용은 포함하지 않습니다.</aside><div className="emotion-list">{active.map(s=>{const stats=moodStats(data.moodHistory.filter(m=>m.ownerId===s.id));return <article key={s.id}><h3>{s.avatar} {s.name}</h3><p>총 마음 작성 {stats.total}회 · 👀 함께 보기 {stats.classShare}회 · 🧑‍🏫 선생님과 학생 {stats.teacherPrivate}회 · 🔒 학생만 {stats.selfOnly}회</p><p>감정 분석 가능 기록 {stats.analyzable}회</p><div className="emoji-stats">{Object.entries(stats.counts).map(([emoji,count])=><span key={emoji}>{emoji} × {count}회 · {stats.analyzable?Math.round(count/stats.analyzable*1000)/10:0}%</span>)}</div></article>})}</div><aside>‘학생만 보기’는 유아가 자신의 마음을 스스로 조절하고 표현 범위를 선택한 기록입니다. 횟수만으로 정서 상태를 판단하지 않습니다.</aside></Shell>;
 if(screen==="discoveryManage"){const topic=data.discoveryTopics[classId];return <Shell><Head title={`${cls.name} 오늘의 발견 관리`} back={()=>setScreen("dashboard")}/><div className="settings-card discovery-form"><label>대표 Emoji<input value={topic.emoji} onChange={e=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,emoji:e.target.value}}}))}/></label><label>제목<input value={topic.title} onChange={e=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,title:e.target.value}}}))}/></label><label>짧은 안내<textarea value={topic.guide} onChange={e=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,guide:e.target.value}}}))}/></label><label>시작일<input type="date" value={topic.startDate} onChange={e=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,startDate:e.target.value}}}))}/></label><label>종료일<input type="date" value={topic.endDate} onChange={e=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,endDate:e.target.value}}}))}/></label><label>선택적 교사 음성 안내<SoundRecorder onChange={audio=>patchData(old=>({...old,discoveryTopics:{...old.discoveryTopics,[classId]:{...topic,audio}}}))}/></label></div><button className="primary teacher-example-button" onClick={()=>setScreen("teacherDiscovery")}>🌱 선생님도 해볼게요</button><h2>활동 현황</h2><div className="simple-status">{active.map(s=>{const entry=data.personalEntries.find(e=>e.kind==="discovery"&&e.ownerId===s.id);return <p key={s.id}>{s.avatar} {s.name} · {entry?`완료 · ${privacyLabel(entry.privacyLevel)}`:"미완료"}</p>})}</div></Shell>} if(screen==="settings"){const account=data.accounts.find(a=>a.classId===classId)!;return <Shell><Head title="교사용 설정" back={()=>setScreen("dashboard")}/><div className="settings-card"><label>현재 학급명<input value={cls.name} onChange={e=>updateClass(c=>({...c,name:e.target.value}))}/></label><label>교사 ID<input value={account.teacherId} readOnly/></label><hr/><h3>비밀번호 변경</h3><label>현재 비밀번호<input type="password" value={currentPass} onChange={e=>setCurrentPass(e.target.value)}/></label><label>새 비밀번호<input type="password" value={newPass} onChange={e=>setNewPass(e.target.value)}/></label><label>새 비밀번호 확인<input type="password" value={confirmPass} onChange={e=>setConfirmPass(e.target.value)}/></label>{settingsMessage&&<p>{settingsMessage}</p>}<button onClick={async()=>{if(newPass.length<4)return setSettingsMessage("새 비밀번호는 4자리 이상으로 정해 주세요.");if(newPass!==confirmPass)return setSettingsMessage("새 비밀번호 확인이 일치하지 않아요.");try{if(cloudConfigured())await changeCloudTeacherPassword(currentPass,newPass);setData(old=>demoAuthService.changePassword(classId,currentPass,newPass,old));setCurrentPass("");setNewPass("");setConfirmPass("");setSettingsMessage("비밀번호를 변경했어요.")}catch(e){setSettingsMessage((e as Error).message)}}}>비밀번호 변경</button><button className="logout" onClick={()=>{void endCloudTeacherSession();sessionStorage.setItem("maeum-role","anonymous");sessionStorage.removeItem("maeum-teacher-class");history.replaceState({},"","/");setLoginId("");setLoginPassword("");setScreen("login")}}>로그아웃</button></div></Shell>} if(screen==="manage")return <Shell><Head title={`${cls.name} 유아 관리`} back={()=>setScreen("dashboard")}/><section className="student-access-materials no-print"><h2>🔑 학생 접속자료</h2><p>학생 코드와 새로 발급된 PIN은 교사만 확인할 수 있습니다. PIN 원문은 서버에 저장되지 않습니다.</p><div><button onClick={()=>{if(!confirm("학생 접속정보가 포함된 파일입니다. 안전한 곳에 보관해 주세요. 다운로드할까요?"))return;const rows=active.map((x,i)=>{const c=data.studentCredentials.find(v=>v.studentId===x.id);return [i+1,x.name,c?.studentCode||"",c?.pin||"기존 PIN 확인 불가",x.active?"사용":"비활성"]}),csv="\\uFEFF번호,학생 이름,학생 코드,초기 PIN,활성상태\\n"+rows.map(r=>r.join(",")).join("\\n"),url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download=`${cls.name}-학생접속정보.csv`;a.click();URL.revokeObjectURL(url)}}>📥 학생 접속정보 CSV 다운로드</button><button onClick={()=>setScreen("qrCards")}>▦ QR 카드 관리·다운로드</button><button onClick={()=>{setScreen("qrCards");setTimeout(()=>window.print(),200)}}>🖨 우리 반 마음씨앗 카드 인쇄</button></div></section><section className="manage-head no-print"><label>학급명<input value={cls.name} onChange={e=>updateClass(c=>({...c,name:e.target.value}))}/></label><button type="button" disabled={active.length>=25||cloudSaving} onClick={addStudent}>{cloudSaving?"저장하고 있어요…":"＋ 원아 추가"}</button>{studentCloudMessage&&<p role="status">{studentCloudMessage}</p>}{active.length>=25&&<p>활성 원아는 한 학급에 최대 25명까지 등록할 수 있어요. 기존 원아를 비활성으로 전환한 뒤 추가해 주세요.</p>}</section><div className="manage-list">{cls.students.map(s=>{const credential=data.studentCredentials.find(v=>v.studentId===s.id);return <article key={s.id} className={!s.active?"inactive":""}><select aria-label={`${s.name} 아바타`} value={s.avatar} onChange={e=>updateClass(c=>({...c,students:c.students.map(x=>x.id===s.id?{...x,avatar:e.target.value}:x)}))}>{studentAvatars.map(v=><option key={v}>{v}</option>)}</select><input aria-label="원아 이름" value={s.name} onChange={e=>updateClass(c=>({...c,students:c.students.map(x=>x.id===s.id?{...x,name:e.target.value}:x)}))}/><div className="student-credential"><span>학생 코드 <b>{credential?.studentCode||"발급 중"}</b></span><span>PIN <b>{credential?.pin||"기존 PIN 확인 불가"}</b></span><span>QR <b>{credential?.qrToken?"이 브라우저에서 표시 가능":"기존 카드 사용 가능 · 이미지 표시 불가"}</b></span></div><div className="manage-actions"><button aria-label="앞으로 이동" onClick={()=>updateClass(c=>{const i=c.students.findIndex(x=>x.id===s.id);if(i<1)return c;const students=[...c.students];[students[i-1],students[i]]=[students[i],students[i-1]];return{...c,students}})}>↑</button><button aria-label="뒤로 이동" onClick={()=>updateClass(c=>{const i=c.students.findIndex(x=>x.id===s.id);if(i<0||i===c.students.length-1)return c;const students=[...c.students];[students[i+1],students[i]]=[students[i],students[i+1]];return{...c,students}})}>↓</button><button disabled={!s.active&&active.length>=25} onClick={()=>updateClass(c=>({...c,students:c.students.map(x=>x.id===s.id?{...x,active:!x.active}:x)}))}>{s.active?"활성 → 비활성":active.length>=25?"25명 제한":"비활성 → 활성"}</button><button type="button" disabled={cloudSaving} onClick={()=>{if(confirm(`${s.name}의 PIN을 새로 만들까요? 기존 PIN은 사용할 수 없어요.`))void resetPin(s.id)}}>PIN 새로 만들기</button><button type="button" disabled={cloudSaving} onClick={()=>{if(confirm(`${s.name}의 QR을 새로 만들까요? 기존 QR은 사용할 수 없어요.`))void resetQr(s.id)}}>QR 새로 만들기</button></div></article>})}</div></Shell>;

 if(screen==="today")return <Shell><Head title={`${cls.name} 오늘의 마음`} back={()=>setScreen("dashboard")}/>{teacherKid?<TeacherMoodDetail student={teacherKid} card={moodCard(teacherKid)} selfOnlyDate={[...data.moodHistory].filter(m=>m.ownerId===teacherKid.id&&m.classId===classId&&m.privacyLevel==="self_only"&&new Date(m.createdAt).toDateString()===new Date().toDateString()).sort((x,y)=>y.createdAt-x.createdAt)[0]?.date} close={()=>setTeacherKidId("")}/>:<div className="teacher-students">{active.map(s=>{const latest=[...data.moodHistory].filter(m=>m.ownerId===s.id&&m.classId===classId&&new Date(m.createdAt).toDateString()===new Date().toDateString()).sort((x,y)=>y.createdAt-x.createdAt)[0],made=!!latest,friendDone=data.friendRecords.some(r=>r.from===s.id&&r.classId===classId&&r.date===today());return <article key={s.id}><button className="student-summary" disabled={!made} onClick={()=>setTeacherKidId(s.id)}><i>{s.avatar}</i><b>{s.name}</b><span className={made?"ok":"wait"}>{made?`마음 작성 완료 · ${privacyLabel(latest.privacyLevel)}`:"마음 미작성"}</span><span className={friendDone?"ok":"wait"}>{friendDone?"마음친구 완료":"마음친구 미완료"}</span></button><select value={s.attendance} onChange={e=>updateClass(c=>({...c,students:c.students.map(x=>x.id===s.id?{...x,attendance:e.target.value as ManagedStudent["attendance"]}:x)}))}><option value="present">출석</option><option value="absent">결석</option><option value="excluded">활동 제외</option></select></article>})}</div>}</Shell>;

 if(screen==="together")return <Shell><TogetherTop title={`${cls.name} 교사와 함께하기`} exit={()=>openTogetherExit("together")}/><aside>교사가 학생을 직접 선택하는 수업·연습 전용 화면입니다. 일반 학생 입장과 분리되어 있어요.</aside><div className="together-menu"><button onClick={()=>{setGuidedMode("practice");setScreen("practiceList")}}><i>🌱</i><b>연습해보기</b><small>학생과 옆에서 천천히 연습해요</small></button><button onClick={()=>setScreen("groupSelect")}><i>💛</i><b>다 같이 해보기</b><small>우리 반 친구들이 차례로 참여해요</small></button><button onClick={()=>setScreen("togetherShare")}><i>👀</i><b>오늘 함께 보기</b><small>공개 가능한 작품을 교사가 골라요</small></button></div></Shell>;
 if(screen==="practiceList")return <Shell><TogetherTop title="🌱 연습할 친구를 골라요" exit={()=>openTogetherExit("practiceList")}/><p className="together-guide">교사가 학생 옆에서 카드를 눌러 주세요.</p><div className="guided-kids">{active.map(x=><button key={x.id} onClick={()=>{if(confirm(`${x.name}과 함께 해볼까요?`)){setKidId(x.id);setGuidedMode("practice");clearWorking();setScreen("guidedHome")}}}><i>{x.avatar}</i><b>{x.name}</b></button>)}</div></Shell>;
 if(screen==="guidedHome"&&kid){const f=data.features[classId],items=[f.mood&&{screen:"mood" as Screen,icon:"💛",name:"오늘 내 마음"},f.capture&&{screen:"capture" as Screen,icon:"📸",name:"내 보물 찰칵"},f.discovery&&{screen:"discovery" as Screen,icon:"🔎",name:"오늘의 발견"}].filter(Boolean) as {screen:Screen;icon:string;name:string}[];return <Shell><TogetherTop title={`${kid.avatar} ${kid.name}과 함께 해볼까요?`} exit={()=>openTogetherExit("guidedHome")}/><aside>지금 하는 활동만 보여요. 과거 기록과 개인 마음편지는 이 화면에서 열리지 않습니다.</aside><div className="guided-actions">{items.map(x=><button key={x.screen} onClick={()=>{clearWorking();setScreen(x.screen)}}><i>{x.icon}</i><b>{x.name}</b></button>)}</div><button className="next-friend" onClick={()=>{setKidId("");setScreen("practiceList")}}>다른 친구 고르기</button></Shell>}
 if(screen==="guidedDone"&&kid)return <Shell><div className="guided-success"><i>🌱</i><h1>잘했어요!</h1><p>{kid.name}의 활동을 안전하게 담았어요.</p><div><button onClick={()=>{setKidId("");setScreen("practiceList")}}>다음 친구</button><button onClick={()=>{setKidId("");setGuidedMode("");setScreen("together")}}>👋 활동 끝내기</button></div></div></Shell>;
 if(screen==="groupSelect"){const f=data.features[classId],choices=[f.mood&&{id:"mood" as const,icon:"💛",name:"오늘 내 마음"},f.discovery&&{id:"discovery" as const,icon:"🔎",name:"오늘의 발견"},f.capture&&{id:"capture" as const,icon:"📸",name:"내 보물 찰칵"}].filter(Boolean) as {id:"mood"|"discovery"|"capture";icon:string;name:string}[];return <Shell><TogetherTop title="💛 다 같이 해보기" exit={()=>openTogetherExit("groupSelect")}/><h2>오늘 함께 할 활동을 골라 주세요.</h2><div className="guided-actions">{choices.map(x=><button key={x.id} onClick={()=>{setGuidedMode("group");setGroupActivity(x.id);setGroupCompleted([]);setGroupSkipped([]);setScreen("groupList")}}><i>{x.icon}</i><b>{x.name}</b></button>)}</div></Shell>}
 if(screen==="groupList"){
  const labels={mood:"💛 오늘 내 마음",capture:"📸 내 보물 찰칵",discovery:"🔎 오늘의 발견"};
  return <Shell><TogetherTop title={labels[groupActivity]} exit={()=>openTogetherExit("groupList")}/><h2>우리 반 친구들이 차례로 담아볼까요?</h2><p className="privacy-reminder">이 화면에는 감정이나 작품 내용 대신 참여 여부만 보여요.</p><div className="guided-kids group-progress">{active.map(x=>{const done=groupCompleted.includes(x.id),skipped=groupSkipped.includes(x.id);return <article key={x.id} className={done?"done":skipped?"skipped":""}><button disabled={done||skipped} onClick={()=>{if(!confirm(`${x.name} 차례를 시작할까요?`))return;setKidId(x.id);clearWorking();setScreen(groupActivity)}}><i>{x.avatar}</i><b>{x.name}</b><span>{done?"✓ 했어요":skipped?"오늘은 쉬어요":"○ 아직"}</span></button>{!done&&!skipped&&<button className="skip" onClick={()=>setGroupSkipped(old=>[...old,x.id])}>오늘 참여하지 않음</button>}</article>})}</div><button className="next-friend" onClick={()=>{setGuidedMode("");setKidId("");setScreen("together")}}>활동 마치기</button></Shell>
 } if(screen==="togetherShare"){const moods=data.moodHistory.filter(x=>x.classId===classId&&x.privacyLevel==="class_share"),personal=data.personalEntries.filter(x=>x.classId===classId&&x.privacyLevel==="class_share");return <Shell><TogetherTop title="👀 오늘 함께 보기" exit={()=>openTogetherExit("togetherShare")}/><aside>함께 보기를 선택한 자료만 목록에 있습니다. 교사가 열어볼 자료를 직접 골라 주세요.</aside><div className="shareable-list">{moods.map(x=><details key={x.id}><summary>💛 오늘 내 마음 · {x.date}</summary><PrintableCard data={{id:x.id,kind:"오늘 내 마음",name:"우리 반 친구",date:x.date,emoji:x.a+x.b,drawing:x.drawing}} showActions={false}/></details>)}{personal.map(x=><details key={x.id}><summary>{x.kind==="capture"?"📸 내 보물 찰칵":"🔎 오늘의 발견"} · {x.date}</summary><PrintableCard data={personalCard(x)} showActions={false}/></details>)}</div>{!moods.length&&!personal.length&&<Empty text="함께 볼 수 있는 자료가 아직 없어요."/>}</Shell>}
